import pandas as pd


def run(inputs: dict) -> dict:
    target_state = inputs['target_state']
    cdc_events = inputs['cdc_events']

    # 1. Deduplicate events by seq (at-least-once delivery -> apply once)
    events = cdc_events.drop_duplicates(subset=['seq'], keep='first').sort_values('seq')

    # Build initial per-order state from target_state, and remember the
    # watermark (last_seq) used for the replay guard.
    state = {}
    guard_seq = {}
    for _, row in target_state.iterrows():
        oid = row['order_id']
        state[oid] = {
            'status': row['status'],
            'amount': row['amount'],
            'last_seq': row['last_seq'],
            'exists': True,
            'deleted_seq': None,
        }
        guard_seq[oid] = row['last_seq']

    # 2 & 3. Apply events, in seq order, honoring the per-order replay guard.
    for _, ev in events.iterrows():
        oid = ev['order_id']
        seq = ev['seq']
        op = ev['op']

        if oid in guard_seq and seq <= guard_seq[oid]:
            continue

        if oid not in state:
            state[oid] = {
                'status': None,
                'amount': None,
                'last_seq': None,
                'exists': False,
                'deleted_seq': None,
            }
        s = state[oid]

        if op in ('I', 'U'):
            if s['exists']:
                s['status'] = ev['status']
                if op == 'U':
                    # 'U' with NULL amount leaves existing amount unchanged
                    if pd.notna(ev['amount']):
                        s['amount'] = ev['amount']
                    # else keep existing amount
                else:
                    # 'I' on existing row: update amount to event amount (as is)
                    s['amount'] = ev['amount']
            else:
                # create new row from scratch
                s['status'] = ev['status']
                s['amount'] = ev['amount']
                s['exists'] = True

            s['last_seq'] = seq
            s['deleted_seq'] = None

        elif op == 'D':
            if s['exists']:
                s['exists'] = False
                s['status'] = None
                s['amount'] = None
                s['last_seq'] = seq
                s['deleted_seq'] = seq
            # 'D' for a missing order does nothing
        # unknown op: ignore (not specified)

    # 4. Build new_state: orders with a surviving row
    new_state_rows = []
    tombstone_rows = []

    for oid, s in state.items():
        if s['exists']:
            new_state_rows.append({
                'order_id': oid,
                'status': s['status'],
                'amount': s['amount'],
                'last_seq': s['last_seq'],
            })
        else:
            # Had a row at some point (either originally or created) and
            # last applied event was 'D'
            if s['deleted_seq'] is not None:
                tombstone_rows.append({
                    'order_id': oid,
                    'deleted_seq': s['deleted_seq'],
                })

    new_state = pd.DataFrame(new_state_rows, columns=['order_id', 'status', 'amount', 'last_seq'])
    tombstones = pd.DataFrame(tombstone_rows, columns=['order_id', 'deleted_seq'])

    if len(new_state) > 0:
        new_state['order_id'] = new_state['order_id'].astype(target_state['order_id'].dtype, errors='ignore')
        new_state['last_seq'] = new_state['last_seq'].astype(target_state['last_seq'].dtype, errors='ignore')

    if len(tombstones) > 0:
        tombstones['order_id'] = tombstones['order_id'].astype(target_state['order_id'].dtype, errors='ignore')
        tombstones['deleted_seq'] = tombstones['deleted_seq'].astype(cdc_events['seq'].dtype, errors='ignore')

    return {
        'new_state': new_state,
        'tombstones': tombstones,
    }
